	logger = system.util.getLogger("Navigation")
	class NavigationItem():
		def __init__(self, navigationItemId, label, material_icon=None, navigation_path=None,
	                 parent_navigation_item_id=None,parent_sub_navigation_item_id=None,parent_sub_sub_navigation_item_id=None, include_on_mobile=None):
			self.id = navigationItemId
			self.label = label
			self.material_icon = material_icon
			self.navigation_path = navigation_path
			self.navigation_item_children = []
			self.navigation_item_sub_children = []
			self.navigation_item_sub_sub_children = []
			self.parent_navigation_item_id = parent_navigation_item_id
			self.parent_sub_navigation_item_id = parent_sub_navigation_item_id
			self.parent_sub_sub_navigation_item_id = parent_sub_sub_navigation_item_id
			self.include_on_mobile = include_on_mobile
			self.required_roles = []


		def addNavigationItemChild(self, child):
			self.navigation_item_children.append(child)

		def addNavigationItemSubChild(self, sub_child):
			self.navigation_item_sub_children.append(sub_child)

		def addNavigationItemSubSubChild(self, sub_sub_child):
			self.navigation_item_sub_sub_children.append(sub_sub_child)

		def addRequiredRole(self, role):
			self.required_roles.append(role)

		@classmethod
		def getNavigationItems(cls):
			tagData = system.tag.readBlocking(["[default]Navigation/Navigation data"])
			data = system.dataset.sort(tagData[0].value,"id")
			data = system.dataset.toPyDataSet(data)
			parents, children, sub_children, sub_sub_children = [], [], [], []
			for row in data:
				id = row['id']
				label = row['label']
				material_icon = row['material_icon']
				navigation_path = row['navigation_path']
				parent_navigation_item_id = row['parent_navigation_item_id']
				parent_sub_navigation_item_id = row['parent_sub_navigation_item_id']
				parent_sub_sub_navigation_item_id = row['parent_sub_sub_navigation_item_id']
				required_roles = row['required_roles']
				include_on_mobile = row['include_on_mobile']

				navItem = NavigationItem(id, label, material_icon, navigation_path, parent_navigation_item_id, parent_sub_navigation_item_id, parent_sub_sub_navigation_item_id, include_on_mobile)
				mobile = self.session.custom.mobile
				if required_roles is not None:
					for role in required_roles.split(','):
						navItem.addRequiredRole(role.strip())
#				if (True in [True if role in navItem.required_roles else False for role in ([] if self.session.props.auth.user.roles == None else self.session.props.auth.user.roles)]) and (not mobile or include_on_mobile) and ('Ontslag' not in ([] if self.session.props.auth.user.roles == None else self.session.props.auth.user.roles)):
				if 1==1:
					if label != "":
						if parent_navigation_item_id is None and parent_sub_navigation_item_id is None and parent_sub_sub_navigation_item_id is None:
							parents.append(navItem)
						elif parent_navigation_item_id is not None and parent_sub_navigation_item_id is None and parent_sub_sub_navigation_item_id is None:
							children.append(navItem)
						elif parent_navigation_item_id is None and parent_sub_navigation_item_id is not None and parent_sub_sub_navigation_item_id is None:
							sub_children.append(navItem)
						elif parent_navigation_item_id is None and parent_sub_navigation_item_id is None and parent_sub_sub_navigation_item_id is not None:
							sub_sub_children.append(navItem)

			for sub_sub_child in sub_sub_children:
				sub_child = next((x for x in sub_children if x.id == sub_sub_child.parent_sub_sub_navigation_item_id), None)
				try:
					sub_child.addNavigationItemSubSubChild(sub_sub_child)
				except:
					logger.error("Creating navigation failed because id: {}. Make sure the folder with this id has all roles that are used for the pages in this folder.".format(sub_sub_child.parent_sub_sub_navigation_item_id))

			for sub_child in sub_children:
				child = next((x for x in children if x.id == sub_child.parent_sub_navigation_item_id), None)
				try:
					child.addNavigationItemSubChild(sub_child)
				except:
					logger.error("Creating navigation failed because id: {}. Make sure the folder with this id has all roles that are used for the pages in this folder.".format(sub_child.parent_sub_navigation_item_id))

			for child in children:
				parent = next((x for x in parents if x.id == child.parent_navigation_item_id), None)
				try:
					parent.addNavigationItemChild(child)
				except:
					logger.error("Creating navigation failed because id: {}. Make sure the folder with this id has all roles that are used for the pages in this folder.".format(child.parent_navigation_item_id))

			return parents


	def createNavigationDict(navigationItem):
		defaultBody = {
						      "viewPath": "Library/SharedDocked/Templates/NavItems",
						      "viewParams": {},
						      "useDefaultViewWidth": False,
						      "useDefaultViewHeight": False,
						      "height": "auto",
						      "style": {
						        "classes": "",
						        "margin": 0
						      }
						    }

		navigationDict = {"expanded": False, 'body':defaultBody}
		navigationDict['target'] = navigationItem.navigation_path
		navigationDict['body']['viewParams'] = {"list":[]}
		navigationDict['header'] = {
			    				      "toggle": {
			    				        "enabled": True,
			    				        "expandedIcon": {
			    				          "path": "material/expand_less",
			    				          "color": "",
			    				          "style": {
			    				            "classes": ""
			    				          }
			    				        },
			    				        "collapsedIcon": {
			    				          "path": "material/expand_more",
			    				          "color": "",
			    				          "style": {
			    				            "classes": ""
			    				          }
			    				        }
			    				      },
			    				      "content": {
			    				        "type": "text",
			    				        "text":  navigationItem.label,
			    				        "useDefaultViewWidth": False,
			    				        "useDefaultViewHeight": False,
			    				        "viewPath": "",
			    				        "viewParams": {},
			    				        "style": {
			    				          "classes": "",
			    				          "textAlign": "left"
			    				        }
			    				      },
			    				      "height": "40px",
			    				      "reverse": True,
			    				      "style": {
			    				        "classes": ""
			    				      }
			    				    }	
		for subSubChildNavItem in navigationItem.navigation_item_sub_sub_children:
			navigationDict['body']['viewParams']['list'].append(createNavigationDict(subSubChildNavItem))
		for subChildNavItem in navigationItem.navigation_item_sub_children:
			navigationDict['body']['viewParams']['list'].append(createNavigationDict(subChildNavItem))
		for childNavItem in navigationItem.navigation_item_children:
			navigationDict['body']['viewParams']['list'].append(createNavigationDict(childNavItem))

		return navigationDict


	def createNavigationList(navigationItems):
	    output = []	   
	    for navigationItem in navigationItems:	        
	            output.append(createNavigationDict(navigationItem))
	    return output

	self.getChild("root").getChild("Accordion").props.items = createNavigationList(NavigationItem.getNavigationItems())

